import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    my_c = 0
    op_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    for a in op:
        if a == 'C':
            op_c += 1
    my_d = n - my_c
    op_d = n - op_c

    # Single probe for pure cooperator at round 11 (n=10)
    if n == 10 and op_d == 0 and my_d == 0:
        return 'D'
    # After probe, cooperate once to give opponent chance to retaliate
    if n == 11 and op_d == 0 and my_d == 1:
        return 'C'
    # Exploit pure cooperator: if opponent never defected and we have defected, keep defecting
    if n >= 12 and op_d == 0 and my_d > 0:
        return 'D'

    # If opponent never cooperated, defect always
    if op_c == 0:
        return 'D'

    # If opponent mostly cooperative, be nice until provoked
    if op_c >= n - max(1, n // 10):
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # If opponent mostly defects, exploit a bit but avoid DD
    if op_c <= n // 3:
        if me[-1] == 'D' and op[-1] == 'D':
            return 'C'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Mid game: tit-for-tat with forgiveness
    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        # Opponent defected, we cooperated
        if op_c > n // 2:
            return 'C'  # forgive to restore cooperation
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated
    if n == 99:
        return 'D'
    if n > 85:
        return 'D' if rng.random() < 0.35 else 'C'
    return 'C'
